/* 학습 해설
 * Libfdt 16bit endian·저장byte와왕복
 * DTB의block/offset/tag/가변record/버전과big-endian고정폭자료형·byte변환·Checkerannotation·platformfallback의원리와사용법을읽습니다.
 * 16bithelper는메모리 byte0을 8bit올리고 byte1과 OR합니다. nativeendianness에맞는 fdt16_t값을만들어저장하면 big-endianbyte가됩니다. 반대 helper도같은 byte조합으로 CPU값을복원합니다. 정수숫자를항상무조건 swap한다고설명하면 big-endianCPU에서틀립니다.
 * 모든 65536입력의저장 byte[x>>8,x&255]와왕복값을실제원문으로검산했습니다. fixture는 nativeLE이고다른 CPU실행은별도입니다.
 */
static inline fdt16_t cpu_to_fdt16(uint16_t x)
{
	return (FDT_FORCE fdt16_t)CPU_TO_FDT16(x);
}

static inline uint32_t fdt32_to_cpu(fdt32_t x)
{
	return (FDT_FORCE uint32_t)CPU_TO_FDT32(x);
}
static inline fdt32_t cpu_to_fdt32(uint32_t x)
{
	return (FDT_FORCE fdt32_t)CPU_TO_FDT32(x);
}

static inline uint64_t fdt64_to_cpu(fdt64_t x)
{
	return (FDT_FORCE uint64_t)CPU_TO_FDT64(x);
}
static inline fdt64_t cpu_to_fdt64(uint64_t x)
{
	return (FDT_FORCE fdt64_t)CPU_TO_FDT64(x);
}
#undef CPU_TO_FDT64
#undef CPU_TO_FDT32
#undef CPU_TO_FDT16
#undef EXTRACT_BYTE

