/**********************************************************************/
/* Checking controls                                                  */
/**********************************************************************/

#ifndef FDT_ASSUME_MASK
#define FDT_ASSUME_MASK 0
#endif

/*
 * Defines assumptions which can be enabled. Each of these can be enabled
 * individually. For maximum safety, don't enable any assumptions!
 *
 * For minimal code size and no safety, use ASSUME_PERFECT at your own risk.
 * You should have another method of validating the device tree, such as a
 * signature or hash check before using libfdt.
 *
 * For situations where security is not a concern it may be safe to enable
 * ASSUME_SANE.
 */

/* 학습 해설
 * Libfdt ORDER·명세와생성도구의배치차이
 * 정렬·probe반환·rawpointer/entrystride·endianload·작성중상태·자료/인자/library가정·조건부검사와사용계약을읽습니다.
 * ORDER bit4는 reserve→structure→strings순서를가정합니다. 주석은이순서가 device-tree명세가강제하는것은아니지만 libfdt와 compiler의일반배치라고설명하며 fdt_open_into의재배치확인/수정능력을줄인다고합니다. format허용범위와도구편의배치를구별합니다.
 * fixture의 40→56→128순서를 example로읽습니다. 이 dataset이모든허용 DTB배치를대표한다고말하지않습니다.
 */
	ASSUME_LIBFDT_ORDER	= 1 << 4,

	/*
	 * This assumes that libfdt itself does not have any internal bugs. It
	 * drops certain checks that should never be needed unless libfdt has an
	 * undiscovered bug.
	 *
	 * This can generally be considered safe to enable.
	 */
	ASSUME_LIBFDT_FLAWLESS	= 1 << 5,
};

/**
 * can_assume_() - check if a particular assumption is enabled
 *
 * @mask: Mask to check (ASSUME_...)
 * @return true if that assumption is enabled, else false
 */
static inline bool can_assume_(int mask)
{
	return FDT_ASSUME_MASK & mask;
}

/** helper macros for checking assumptions */
#define can_assume(_assume)	can_assume_(ASSUME_ ## _assume)

/* 학습 해설
 * Libfdt FLAWLESS·library 내부정상성 전제
