/* 학습 해설
 * Libfdt 최소probe·정렬·완성/작성중·지원version
 * 고정원본의DTBprobe/header/bounds·overflow·version·tag가변record·depth-first/subnode·NULstring검색·overlapmove의원리와사용법을읽습니다.
 * ro_probe는 header의 totalsize를얻고전제가없으면 8byte정렬·완성 magic또는 SWmagic·지원 version/lastcompatible·작성중 structure상태를검사합니다. 최소읽기 headerprobe이며각 block의모든 bounds나전체 tree를여기서순회하지않습니다. VALID_DTB전제가켜지면앞에서 totalsize를반환하는경로입니다.
 * magic/정렬/작성중상태의오류코드를조건표로적습니다. firstpage remap의단순 magic검사와이최소 libraryprobe도서로다른검사층입니다.
 */
int32_t fdt_ro_probe_(const void *fdt)
{
	uint32_t totalsize = fdt_totalsize(fdt);

	if (can_assume(VALID_DTB))
		return totalsize;

	/* The device tree must be at an 8-byte aligned address */
	if ((uintptr_t)fdt & 7)
		return -FDT_ERR_ALIGNMENT;

	if (fdt_magic(fdt) == FDT_MAGIC) {
		/* Complete tree */
		if (!can_assume(LATEST)) {
			if (fdt_version(fdt) < FDT_FIRST_SUPPORTED_VERSION)
				return -FDT_ERR_BADVERSION;
			if (fdt_last_comp_version(fdt) >
					FDT_LAST_SUPPORTED_VERSION)
				return -FDT_ERR_BADVERSION;
		}
	} else if (fdt_magic(fdt) == FDT_SW_MAGIC) {
		/* Unfinished sequential-write blob */
		if (!can_assume(VALID_INPUT) && fdt_size_dt_struct(fdt) == 0)
			return -FDT_ERR_BADSTATE;
	} else {
		return -FDT_ERR_BADMAGIC;

/* 학습 해설
 * Libfdt probe 결과·INT32_MAX 경계와음수오류
 * 고정원본의DTBprobe/header/bounds·overflow·version·tag가변record·depth-first/subnode·NULstring검색·overlapmove의원리와사용법을읽습니다.
 * 전제없는 probe는 totalsize<INT32_MAX이면크기를반환하고같거나크면 TRUNCATED음수오류입니다. 정상크기와오류를같은 int32반환으로표현할수있도록수치범위를제한합니다. INT_MAX초과검사의 fdt_check_header와 equality조건이동일하다고설명하지않습니다.
 * fixture의 135성공과 INT32_MAX거부를계산합니다. header기술과반환자료형의오류표현범위를연결합니다.
 */
int32_t fdt_ro_probe_(const void *fdt)
{
	uint32_t totalsize = fdt_totalsize(fdt);

	if (can_assume(VALID_DTB))
		return totalsize;

	/* The device tree must be at an 8-byte aligned address */
	if ((uintptr_t)fdt & 7)
		return -FDT_ERR_ALIGNMENT;

